from typing import List

def harvest_crops(K: int, C: List[List[int]]) -> int:
    col = [0] * (K + 2)              # padded: col[j+1] stores column j
    for cell in C:
        c = cell[1]
        w = cell[2] if len(cell) > 2 else 1
        col[c + 1] += w
    return max(col[j] + col[j + 2] for j in range(K))
